import { useEffect, useMemo, useRef, useState, type ChangeEvent, type Dispatch, type FormEvent, type KeyboardEvent, type SetStateAction } from 'react'
import { canManageInstitution, canManageLearningContent, roleLabel } from './lib/access'
import { chapters, chaptersFor, deepLessons, officialResources, questionBank, subjectById, subjects } from './lib/content'
import { demoProfiles } from './lib/demoData'
import { examDraftKey, mockExamQuestions, remainingSeconds } from './lib/exam'
import { completePasswordRecovery, getProfileForUser, hasRecoveryToken, isSupabaseConfigured, requestPasswordReset, supabase, updatePreferredMedium } from './lib/supabase'
import { emptyStore, loadMedium, loadStore, loadTheme, recordAttempt, saveMedium, saveStore, saveTheme } from './lib/store'
import type { AttemptRecord, BankQuestion, Chapter, Medium, Profile, Role, StoreState, Theme } from './types'

type View = 'overview'|'learn'|'practice'|'papers'|'exams'|'performance'|'bookmarks'|'admin'|'settings'
const nav: {id:View; label:string; icon:string; student?:boolean; staff?:boolean}[] = [
  {id:'overview',label:'Overview',icon:'home'}, {id:'learn',label:'Learn by chapter',icon:'book'},
  {id:'practice',label:'MCQ practice',icon:'check'}, {id:'papers',label:'Official resources',icon:'file'},
  {id:'exams',label:'Mock examination',icon:'clipboard'}, {id:'performance',label:'My performance',icon:'chart',student:true},
  {id:'bookmarks',label:'Bookmarks & revision',icon:'bookmark',student:true}, {id:'admin',label:'School workspace',icon:'shield',staff:true}
]

const navLabels:Record<Medium,Record<View,string>>={
 english:{overview:'Home',learn:'Learn',practice:'Practice',papers:'Papers',exams:'Mock tests',performance:'Progress',bookmarks:'Saved',admin:'School',settings:'Settings'},
 kannada:{overview:'ಮುಖಪುಟ',learn:'ಕಲಿಯಿರಿ',practice:'ಅಭ್ಯಾಸ',papers:'ಪ್ರಶ್ನೆಪತ್ರಿಕೆ',exams:'ಮಾದರಿ ಪರೀಕ್ಷೆ',performance:'ಪ್ರಗತಿ',bookmarks:'ಉಳಿಸಿದವು',admin:'ಶಾಲೆ',settings:'ಸೆಟ್ಟಿಂಗ್‌ಗಳು'}
}

